package com.surakshasetu;

import android.Manifest; import android.app.*; import android.content.*; import android.graphics.*; import android.graphics.drawable.GradientDrawable; import android.net.Uri; import android.os.Bundle; import android.provider.Settings; import android.view.*; import android.widget.*;

/** ScamPause: a decision firewall, not another caller-ID screen. */
public class MainActivity extends Activity {
 private LinearLayout root; private TextView headline,detail; private float d; private android.content.SharedPreferences prefs;
 @Override public void onCreate(Bundle b){super.onCreate(b);d=getResources().getDisplayMetrics().density;prefs=getSharedPreferences("settings",MODE_PRIVATE);ProtectionService.start(this);if(!prefs.getBoolean("onboarding_complete",false))showOnboarding();requestPermissions(new String[]{Manifest.permission.RECEIVE_SMS,Manifest.permission.READ_PHONE_STATE,Manifest.permission.READ_CALL_LOG,Manifest.permission.POST_NOTIFICATIONS},42);renderProtected();}
 private TextView t(String s,int sp,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(sp);v.setTextColor(c);v.setPadding(dp(0),dp(8),dp(0),dp(8));return v;}
 private Button btn(String s,int color){Button b=new Button(this);b.setText(s);b.setTextSize(15);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackground(round(color,16));b.setOnClickListener(v->{});return b;}
 private GradientDrawable round(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}
 private int dp(int x){return Math.round(x*d);}
 private void base(){ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(24),dp(22),dp(24),dp(28));root.setBackgroundColor(Color.WHITE);s.addView(root);setContentView(s);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.surakshasetu_logo);bar.addView(logo,new LinearLayout.LayoutParams(dp(42),dp(42)));bar.addView(t("SurakshaSetu",20,Color.rgb(10,51,88)));root.addView(bar);}
 private void renderProtected(){base();headline=t("You’re protected",30,Color.rgb(11,31,51));detail=t("SurakshaSetu is watching for the pattern of a scam—not just a caller.",16,Color.DKGRAY);root.addView(headline);root.addView(detail);root.addView(card("SCAMPAUSE ACTIVE","If a call, message, link and payment request form a pattern, we will ask you to pause before you act.",Color.rgb(30,158,106)));root.addView(t("Evidence History",18,Color.rgb(11,31,51)));String history=SecureStore.get(this);root.addView(t(history.isEmpty()?"No evidence capsules saved yet.":"Your saved incident capsules are encrypted on this phone.",13,Color.GRAY));Button evidence=btn("View saved evidence",Color.rgb(10,51,88));evidence.setOnClickListener(v->showEvidenceHistory());root.addView(evidence);root.addView(t("Try the experience",13,Color.GRAY));Button demo=btn("Simulate a risky interaction",Color.rgb(10,51,88));demo.setOnClickListener(v->renderPause());root.addView(demo);Button settings=btn("Protection settings",Color.rgb(10,51,88));settings.setOnClickListener(v->showSettings());root.addView(settings);root.addView(t("No cloud account required. Analysis stays on this phone.",13,Color.GRAY));}
 private void renderPause(){base();headline=t("Pause. This interaction has 3 scam signals.",28,Color.rgb(135,35,30));detail=t("The conversation creates urgency, asks for credentials, and directs you to an unverified action.",16,Color.DKGRAY);root.addView(headline);root.addView(detail);root.addView(card("SCAM JOURNEY","Unknown caller  →  urgent KYC message  →  suspicious link  →  payment request",Color.rgb(255,244,218)));root.addView(t("What would you like to do?",16,Color.rgb(11,31,51)));Button safe=btn("I’m safe",Color.rgb(30,158,106));safe.setOnClickListener(v->renderProtected());root.addView(safe);Button trust=btn("Ask someone I trust",Color.rgb(10,51,88));trust.setOnClickListener(v->askTrusted());root.addView(trust);Button scam=btn("I may be getting scammed",Color.rgb(160,45,38));scam.setOnClickListener(v->renderRecovery());root.addView(scam);Button back=btn("Back to protection",Color.GRAY);back.setOnClickListener(v->renderProtected());root.addView(back);}
 private void renderRecovery(){base();headline=t("You’re not alone.",30,Color.rgb(11,31,51));detail=t("Stop contact now. Do not pay, share an OTP, or install remote-access software.",16,Color.DKGRAY);root.addView(headline);root.addView(detail);root.addView(card("RECOVERY MODE","1  Stop contact\n2  Call your bank\n3  Preserve screenshots and numbers\n4  Call cyber-fraud helpline 1930",Color.rgb(255,244,218)));Button call=btn("Call 1930",Color.rgb(160,45,38));call.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:1930"))));root.addView(call);Button evidence=btn("Save evidence capsule",Color.rgb(10,51,88));evidence.setOnClickListener(v->saveEvidence());root.addView(evidence);Button history=btn("View evidence history",Color.rgb(10,51,88));history.setOnClickListener(v->showEvidenceHistory());root.addView(history);Button back=btn("Return to protection",Color.rgb(30,158,106));back.setOnClickListener(v->renderProtected());root.addView(back);}
 private TextView card(String title,String body,int color){TextView v=t(title+"\n\n"+body,15,Color.rgb(11,31,51));v.setBackground(round(Color.rgb(247,249,251),20));v.setPadding(dp(20),dp(18),dp(20),dp(18));v.setCompoundDrawablesWithIntrinsicBounds(0,0,0,0);return v;}
 private void askTrusted(){new AlertDialog.Builder(this).setTitle("Trusted Circle").setMessage("This MVP keeps the request local. In the next version, choose a contact and send them the risk summary without sharing the original message.").setNegativeButton("Cancel",null).setPositiveButton("Save request",(d,w)->Alert.show(this,"Trusted check-in ready","Open your trusted contact and share: ‘Can you verify this interaction with me?’")).show();}
 private void saveEvidence(){String old=SecureStore.get(this);String item=java.text.DateFormat.getDateTimeInstance().format(new java.util.Date())+"\nScamPause incident\nSignals: urgency, credential request, unverified action";SecureStore.put(this,item+(old.isEmpty()?"":"\n---\n"+old));Alert.show(this,"Evidence capsule saved","Encrypted and stored locally. Open Evidence History to review or share it.");}
 private void showEvidenceHistory(){String h=SecureStore.get(this);if(h.isEmpty()){new AlertDialog.Builder(this).setTitle("Evidence History").setMessage("No evidence capsules saved yet.").setPositiveButton("Close",null).show();return;}new AlertDialog.Builder(this).setTitle("Evidence History").setMessage(h).setNegativeButton("Close",null).setPositiveButton("Share",(d,w)->{Intent i=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,h);startActivity(Intent.createChooser(i,"Share evidence"));}).show();}
 private void showOnboarding(){new AlertDialog.Builder(this).setTitle("Welcome to SurakshaSetu").setMessage("SurakshaSetu quietly watches for scam patterns across messages, notifications, and calls. It pauses you before a risky action and keeps evidence on this phone.\n\nYou stay in control: permissions can be changed any time in Android Settings.").setCancelable(false).setNegativeButton("Set up later",(d,w)->prefs.edit().putBoolean("onboarding_complete",true).apply()).setPositiveButton("I understand",(d,w)->prefs.edit().putBoolean("onboarding_complete",true).apply()).show();}
 private void showSettings(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),dp(4),dp(20),0);Switch sms=new Switch(this);sms.setText("Message protection");sms.setChecked(prefs.getBoolean("sms_enabled",true));sms.setOnCheckedChangeListener((b,c)->prefs.edit().putBoolean("sms_enabled",c).apply());box.addView(sms);Switch calls=new Switch(this);calls.setText("Call protection");calls.setChecked(prefs.getBoolean("calls_enabled",true));calls.setOnCheckedChangeListener((b,c)->prefs.edit().putBoolean("calls_enabled",c).apply());box.addView(calls);Switch notifs=new Switch(this);notifs.setText("Notification protection");notifs.setChecked(prefs.getBoolean("notifs_enabled",true));notifs.setOnCheckedChangeListener((b,c)->prefs.edit().putBoolean("notifs_enabled",c).apply());box.addView(notifs);new AlertDialog.Builder(this).setTitle("Protection settings").setView(box).setNeutralButton("Android permissions",(d,w)->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())))).setPositiveButton("Done",null).show();}
}
